u='https://smm.org.mk/wp-content/uploads/2023/04/resenija-1.pdf'
def add(s,v,t,tags,reason,statement=None,solution=None):
 id='mkd_2023_'+s;d=json.loads((p/(id+'.json')).read_text());comp=d['competition_raw'];src=u if comp=='Macedonian Mathematical Olympiad' else 'https://mathnet.mit.edu/explorer.html?p='+id
 r[id]={'difficulty':v,'topic':t,'tags':tags,'reason':reason,'competition':comp,'sourceUrl':src,'solutionUrl':src,'sourceName':'Macedonian Mathematical Society — 2023 contest material','solutionKind':'original-exposition'}
 if statement:r[id]['statement']=statement
 if solution:r[id]['solution']=solution
 if v is None:r[id]['quarantine']=True
add('0c29c1',4,'Algebra',['functional equations','symmetry'],'First prove oddness, then swap the inputs to force a constant ratio f(t)/t.',r'Find $f:\mathbb R\to\mathbb R$ satisfying $xf(x+y)+yf(y-x)=f(x^2+y^2)$ for all real $x,y$.',r'Putting $x=y=0$ gives $f(0)=0$. Setting $y=0$ gives $xf(x)=f(x^2)$, and replacing $x$ by $-x$ proves $f(-x)=-f(x)$. Subtract the original equation from its version with $x,y$ exchanged. Oddness gives $$(x-y)f(x+y)=(x+y)f(x-y).$$ Since $x+y$ and $x-y$ can be any two reals, taking the latter equal to one yields $f(t)=ct$, where $c=f(1)$. Direct substitution verifies every real $c$.')
add('09c6cc',3.5,'Number theory',['multiplicative order'],'For p≤q, the order of −a modulo p divides both q and p−1, hence equals one.')
add('b3e2ef',4.5,'Combinatorics',['bipartite graphs','extremal construction'],'Split each colour by floor parity for the upper bound, then attain it simultaneously with paired floors.',r'There are 1000 towers, each with 1000 floors and one resident per floor. Each tower uses all 1000 hat colours once. Residents are friends exactly when their hat colours match and their floor numbers differ by one. Find the greatest possible number of unordered friend pairs.',r'For any fixed colour there are 1000 residents. If $u$ occupy odd floors and $1000-u$ even floors, every friendship joins the two groups. Thus that colour contributes at most $u(1000-u)\le250000$ pairs, for a total at most $250000000$. Attain this by putting colours $1,2,\ldots,1000$ in that floor order in 500 towers, and colours $2,1,4,3,\ldots,1000,999$ in the other 500 towers. For each colour, all 500 residents of the first group are friends with all 500 of the second group. The maximum is $250000000$.')
r['mkd_2023_b3e2ef']['notes']='Replaced the incorrect corpus solution with an independent proof; the answer agrees with the official solution.'
add('9344c6',5.5,'Geometry',['orthocentre','circumcentres','vectors'],'The midpoint of OH lies on three perpendicular bisectors obtained from the circle centres.',r'Let $ABC$ be acute and scalene, with orthocentre $H$. The circle centred at $A$ through $H$ meets $(BHC)$ again at $T_a$; define $T_b,T_c$ cyclically. Prove $H,T_a,T_b,T_c$ concyclic.',r'Let $O$ be the circumcentre and choose vector origin $O$. Write the vertices as $a,b,c$; then $h=a+b+c$, and the circumcentre $S_a$ of $BHC$ has vector $b+c$ (its distances to $B,H,C$ all equal the circumradius). The midpoint $E$ of $OH$ is consequently also the midpoint of $AS_a$. Both $A$ and $S_a$ are equidistant from $H,T_a$, so their line is the perpendicular bisector of $HT_a$; hence $EH=ET_a$. Cyclically $EH=ET_b=ET_c$, proving the result.')
add('1d90f4',None,'Combinatorics',['adjacent swaps'],'Full official solution located, but its long optimality argument is pending complete verification; no numerical rating published.')
add('50a355',5.5,'Combinatorics',['graph theory','bijection'],'For adjacent vertices, uniquely pair their exclusive neighbours using the two-common-neighbours condition.',r'In a finite simple graph, every nonadjacent pair has exactly two common neighbours, and no four vertices induce exactly five edges. Prove that all vertices have equal degree.',r'The graph is connected, since nonadjacent vertices have a common neighbour. Fix adjacent $A,B$. For a neighbour $X$ of $A$ not adjacent to $B$ and distinct from $B$, the nonadjacent pair $X,B$ has common neighbours $A$ and a unique $Y$. The edges $AX,AB,BY,YX$ exist and $BX$ does not, so $AY$ cannot exist: it would give exactly five edges on these four vertices. Thus $Y$ is an exclusive neighbour of $B$. Conversely, the two common neighbours of the nonadjacent pair $A,Y$ are precisely $B,X$, recovering $X$ uniquely. This bijects the exclusive neighbours of $A$ and $B$. Their common neighbours and their mutual edge contribute equally, so their degrees agree. Connectivity finishes.')
add('88c6ee',4,'Algebra',['functional equations','translations'],'Two equilateral triangles sharing a side imply a fixed-distance invariance; intersecting equal-radius circles makes the function constant.',r'A function $f:\mathbb R^2\to\mathbb R$ has $f(A)+f(B)+f(C)=0$ for every unit equilateral triangle $ABC$. Prove $f$ vanishes everywhere.',r'For two unit equilateral triangles on opposite sides of the same base, subtraction gives equal values at their opposite vertices. Those vertices have distance $\sqrt3$, and every pair at that distance arises in this way. Hence $f(P)=f(Q)$ whenever $PQ=\sqrt3$. If $PQ\le2\sqrt3$, choose a point $R$ at distance $\sqrt3$ from both; then $f(P)=f(R)=f(Q)$. Subdivide an arbitrary segment into pieces of length at most $2\sqrt3$ to see that $f$ is constant. The equilateral-triangle condition says three times that constant is zero.')
add('1df9d3',3.5,'Number theory',['construction','prime divisors'],'Take each gap as one plus a sufficiently high power of the product of all small primes; then recurse to define the a-values.')
add('cc62f8',3.5,'Algebra',['recurrences','geometric series'],'The ratios satisfy r(n+1)=(r(n)^3+1)/2; after the first step the summands decrease by at least a factor two.')
